// Core tests: the 15 literal core cases from the fixed spec's fixtures.json
// (vendored verbatim at test/fixtures.json from spec PR #399, head
// e0e721a03f2bb9b7fedb19002eb39a990fc5a3e7; expected values taken verbatim,
// never generated by the product), plus hand-derived boundary and
// validation-order cases. Every extra expected value below was computed
// from the SPEC's stated integer formulas by hand before the product code
// existed.

import assert from "node:assert/strict";
import test from "node:test";
import { run } from "../public/js/core/budget.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

test("structural invariants hold on every success fixture", () => {
  for (const entry of coreCases) {
    if (!entry.expected.ok) continue;
    const { result } = run(entry.input);
    assert.equal(
      result.targets.monthly.needs + result.targets.monthly.wants + result.targets.monthly.savings,
      result.income,
      `${entry.id}: monthly amounts must sum to income`,
    );
    for (const id of ["needs", "wants", "savings"]) {
      assert.equal(
        result.targets.yearly[id],
        result.targets.monthly[id] * 12,
        `${entry.id}: yearly must be monthly * 12`,
      );
      assert.equal(
        result.percentages[id],
        result.variance?.[id]?.targetPercent ?? result.percentages[id],
        entry.id,
      );
    }
    if (result.variance !== null) {
      for (const id of ["needs", "wants", "savings"]) {
        const entryVariance = result.variance[id];
        if (entryVariance === null) {
          assert.equal(result.actuals[id], null, entry.id);
          continue;
        }
        assert.equal(entryVariance.difference, entryVariance.actual - entryVariance.target, entry.id);
        assert.equal(entryVariance.target, result.targets.monthly[id], entry.id);
        assert.ok(entryVariance.actualPercent >= 0, entry.id);
        assert.equal(
          entryVariance.status,
          entryVariance.difference === 0
            ? "on-target"
            : entryVariance.difference > 0
              ? "over"
              : "under",
          entry.id,
        );
      }
    }
    if (result.totals !== null) {
      assert.equal(
        result.totals.actual,
        result.actuals.needs + result.actuals.wants + result.actuals.savings,
        entry.id,
      );
      assert.equal(result.totals.unallocated, result.income - result.totals.actual, entry.id);
      assert.equal(
        result.totals.status,
        result.totals.unallocated === 0
          ? "balanced"
          : result.totals.unallocated > 0
            ? "under"
            : "over",
        entry.id,
      );
    }
  }
});

// Hand-derived: income 1, default split. exact 0.5 / 0.3 / 0.2 -> 1 / 0 /
// 0, sum 1, residual 0. Monthly 1 / 0 / 0, yearly 12 / 0 / 0.
test("hand-derived endpoint: income 1", () => {
  assert.deepEqual(
    run({
      income: "1",
      needsPct: "50",
      wantsPct: "30",
      savingsPct: "20",
      actualNeeds: "",
      actualWants: "",
      actualSavings: "",
    }),
    {
      ok: true,
      result: {
        income: 1,
        percentages: { needs: 50, wants: 30, savings: 20 },
        targets: {
          monthly: { needs: 1, wants: 0, savings: 0 },
          yearly: { needs: 12, wants: 0, savings: 0 },
        },
        actuals: null,
        variance: null,
        totals: null,
      },
    },
  );
});

