// Hand-derived: income 100, 100/0/0 with a single actual filled. Target
// 100 / 0 / 0; actual needs 1 -> difference -99, actualPercent 1.0,
// status under; wants/savings variance null; totals null.
test("hand-derived: single actual, 100/0/0 split", () => {
  assert.deepEqual(
    run({
      income: "100",
      needsPct: "100",
      wantsPct: "0",
      savingsPct: "0",
      actualNeeds: "1",
      actualWants: "",
      actualSavings: "",
    }),
    {
      ok: true,
      result: {
        income: 100,
        percentages: { needs: 100, wants: 0, savings: 0 },
        targets: {
          monthly: { needs: 100, wants: 0, savings: 0 },
          yearly: { needs: 1200, wants: 0, savings: 0 },
        },
        actuals: { needs: 1, wants: null, savings: null },
        variance: {
          needs: {
            actual: 1,
            target: 100,
            difference: -99,
            actualPercent: 1,
            targetPercent: 100,
            status: "under",
          },
          wants: null,
          savings: null,
        },
        totals: null,
      },
    },
  );
});

// Hand-derived: actualPercent half-up at one decimal. income 30000,
// actual wants 1 -> 1/30000*100 = 0.00333...% -> 0.0; actual savings
// 150 -> 0.5% exactly -> 0.5. Needs unfilled.
test("hand-derived: actualPercent rounding to one decimal", () => {
  const outcome = run({
    income: "30000",
    needsPct: "50",
    wantsPct: "30",
    savingsPct: "20",
    actualNeeds: "",
    actualWants: "1",
    actualSavings: "150",
  });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.variance.wants.actualPercent, 0);
  assert.equal(outcome.result.variance.savings.actualPercent, 0.5);
  assert.equal(outcome.result.variance.needs, null);
  assert.equal(outcome.result.totals, null);
});

// Hand-derived: actualPercent half-up tie at the second decimal.
// income 80000, actual needs 1 -> 0.00125% -> 0.0; actual wants 100 ->
// 0.125% -> 0.1 (0.125 rounds to 0.1 at one decimal: 1.25 tenths -> 1);
// actual savings 300 -> 0.375% -> 0.4 (3.75 tenths -> 4).
test("hand-derived: actualPercent half-up ties", () => {
  const outcome = run({
    income: "80000",
    needsPct: "50",
    wantsPct: "30",
    savingsPct: "20",
    actualNeeds: "1",
    actualWants: "100",
    actualSavings: "300",
  });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.variance.needs.actualPercent, 0);
  assert.equal(outcome.result.variance.wants.actualPercent, 0.1);
  assert.equal(outcome.result.variance.savings.actualPercent, 0.4);
});

const valid = {
  income: "60000",
  needsPct: "50",
  wantsPct: "30",
  savingsPct: "20",
  actualNeeds: "",
  actualWants: "",
  actualSavings: "",
};
const errorOf = (input) => run(input).error;

test("SCHEMA: non-objects, arrays, missing, extra, wrong types, accessors", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("60000"), schema);
  assert.deepEqual(errorOf(["60000", "50"]), schema);
  assert.deepEqual(
    errorOf({
      income: "60000",
      needsPct: "50",
      wantsPct: "30",
      savingsPct: "20",
      actualNeeds: "",
      actualWants: "",
    }),
    schema,
  );
  assert.deepEqual(errorOf({ ...valid, extra: "1" }), schema);
  assert.deepEqual(errorOf({ ...valid, income: 60000 }), schema);
  assert.deepEqual(errorOf({ ...valid, needsPct: null }), schema);
  const withAccessor = { ...valid };
  Object.defineProperty(withAccessor, "actualNeeds", {
    enumerable: true,
    get() {
      return "";
    },
  });
  assert.deepEqual(errorOf(withAccessor), schema);
});

test("field order: income, pcts, actuals, then the percent sum", () => {
  assert.deepEqual(errorOf({ ...valid, income: "0", needsPct: "101" }), {
    code: "RANGE",
    field: "income",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, needsPct: "101", wantsPct: "x" }), {
    code: "RANGE",
    field: "needsPct",
    row: null,
  });
  assert.deepEqual(
    errorOf({ ...valid, needsPct: "40", wantsPct: "40", savingsPct: "30", actualNeeds: "x" }),
    { code: "INTEGER_FORMAT", field: "actualNeeds", row: null },
    "per-field validation of the actuals runs before the cross-field sum",
  );
  assert.deepEqual(
    errorOf({ ...valid, needsPct: "40", wantsPct: "40", savingsPct: "30" }),
    { code: "PERCENT_SUM", field: null, row: null },
    "the percent sum is checked last, after all fields pass",
  );
  assert.deepEqual(errorOf({ ...valid, actualNeeds: "x", actualWants: "y" }), {
    code: "INTEGER_FORMAT",
    field: "actualNeeds",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, actualWants: "y", actualSavings: "z" }), {
    code: "INTEGER_FORMAT",
    field: "actualWants",
    row: null,
  });
});

test("per-field order: capacity before empty before grammar before range", () => {
  assert.deepEqual(errorOf({ ...valid, income: "12345678901234567" }), {
    code: "INPUT_LIMIT",
    field: "income",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, needsPct: "12345678901234567" }), {
    code: "INPUT_LIMIT",
    field: "needsPct",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, actualSavings: "12345678901234567" }), {
    code: "INPUT_LIMIT",
    field: "actualSavings",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, income: "" }), {
    code: "EMPTY",
    field: "income",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, needsPct: "" }), {
    code: "EMPTY",
    field: "needsPct",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, income: "100000001" }), {
    code: "RANGE",
    field: "income",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, actualNeeds: "100000001" }), {
    code: "RANGE",
    field: "actualNeeds",
    row: null,
  });
});

test("integer grammar rejects decimals, signs, spaces, leading zeros, exponents", () => {
  for (const bad of [
    "60000.5",
    "060000",
    " 60000",
    "60000 ",
    "+60000",
    "-60000",
    "6e4",
    "60,000",
    "６００００",
  ]) {
    assert.deepEqual(
      errorOf({ ...valid, income: bad }),
      { code: "INTEGER_FORMAT", field: "income", row: null },
      `income ${JSON.stringify(bad)}`,
    );
  }
  assert.deepEqual(errorOf({ ...valid, actualNeeds: "1.5" }), {
    code: "INTEGER_FORMAT",
    field: "actualNeeds",
    row: null,
  });
});

test("percent sums of 99 and 101 fail PERCENT_SUM after each pct passes", () => {
  assert.deepEqual(errorOf({ ...valid, needsPct: "50", wantsPct: "30", savingsPct: "19" }), {
    code: "PERCENT_SUM",
    field: null,
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, needsPct: "50", wantsPct: "30", savingsPct: "21" }), {
    code: "PERCENT_SUM",
    field: null,
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, needsPct: "0", wantsPct: "0", savingsPct: "0" }), {
    code: "PERCENT_SUM",
    field: null,
    row: null,
  });
});

test("boundary values: income 1 and 100,000,000 pass; pct 0 and 100 pass", () => {
  assert.equal(run({ ...valid, income: "1" }).ok, true);
  assert.equal(run({ ...valid, income: "100000000" }).ok, true);
  assert.equal(run({ ...valid, needsPct: "100", wantsPct: "0", savingsPct: "0" }).ok, true);
  assert.equal(run({ ...valid, actualNeeds: "0" }).ok, true);
  assert.equal(run({ ...valid, actualNeeds: "100000000" }).ok, true);
});

test("lone surrogates fail the field grammar, never crash", () => {
  assert.deepEqual(errorOf({ ...valid, income: "60000\uD800" }), {
    code: "INTEGER_FORMAT",
    field: "income",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, needsPct: "5\uD800" }), {
    code: "INTEGER_FORMAT",
    field: "needsPct",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, actualWants: "1\uD800" }), {
    code: "INTEGER_FORMAT",
    field: "actualWants",
    row: null,
  });
});

test("invariants over a deterministic pseudo-random sweep", () => {
  let seed = 20261121;
  const next = () => {
    seed = (seed * 1103515245 + 12345) % 2147483648;
    return seed;
  };
  for (let i = 0; i < 500; i += 1) {
    const income = 1 + (next() % 100000000);
    const a = next() % 101;
    const b = next() % (101 - a);
    const input = {
      income: String(income),
      needsPct: String(a),
      wantsPct: String(b),
      savingsPct: String(100 - a - b),
      actualNeeds: next() % 3 === 0 ? "" : String(next() % 100000001),
      actualWants: next() % 3 === 0 ? "" : String(next() % 100000001),
      actualSavings: next() % 3 === 0 ? "" : String(next() % 100000001),
    };
    const outcome = run(input);
    assert.equal(outcome.ok, true, JSON.stringify(input));
    const { result } = outcome;
    assert.equal(
      result.targets.monthly.needs + result.targets.monthly.wants + result.targets.monthly.savings,
      income,
      JSON.stringify(input),
    );
    for (const id of ["needs", "wants", "savings"]) {
      assert.equal(result.targets.yearly[id], result.targets.monthly[id] * 12);
      assert.ok(result.targets.monthly[id] >= 0);
      if (result.variance?.[id] !== null && result.variance?.[id] !== undefined) {
        const entryVariance = result.variance[id];
        assert.equal(entryVariance.difference, entryVariance.actual - entryVariance.target);
        // actualPercent is a one-decimal number: tenths are integers.
        assert.equal(Math.round(entryVariance.actualPercent * 10), entryVariance.actualPercent * 10);
      }
    }
    const filled = ["needs", "wants", "savings"].filter((id) => input[`actual${id[0].toUpperCase()}${id.slice(1)}`] !== "");
    if (filled.length === 0) {
      assert.equal(result.actuals, null);
      assert.equal(result.variance, null);
      assert.equal(result.totals, null);
    } else if (filled.length < 3) {
      assert.equal(result.totals, null);
    } else {
      assert.notEqual(result.totals, null);
    }
  }
});
